SELECT "nct", "author", "year", "pubmed_id", "cancer_type", "treatment_regimen", "ici_name", "ici_class", "therapy_type", "clinical_setting", "trial_phase", "primary_endpoint" FROM public."clinical_trials" WHERE "cancer_type" ILIKE '%Multiple Myeloma%' AND "therapy_type" = 'Combination therapy' AND "lines_of_treatment" ILIKE '%2L%' OR "lines_of_treatment" ILIKE '%≥2%' OR "lines_of_treatment" ILIKE '%2nd line%' OR "lines_of_treatment" ILIKE '%2nd-line%' OR "lines_of_treatment" ILIKE '%2+'